   "sez": "ambiente",
   "titolo": "Ghana, nel distretto di Ellembelle nasce una brigata contro la plastica",
   "orig": "Ellembelle District launches Eco Brigade to tackle plastic pollution in coastal communities",
   "lead": "Il distretto di Ellembelle, nella Regione Occidentale del Ghana, ha lanciato una «Eco Brigade», una squadra dedicata alla lotta contro l'inquinamento da plastica nelle comunità costiere. L'iniziativa ha l'obiettivo di ripulire il litorale e di garantire un futuro più verde al territorio. Le autorità locali puntano così ad affrontare un problema che colpisce in particolare le zone affacciate sul mare. Lo riferisce 3News.",
   "more": [
    "L'inquinamento da plastica è uno dei principali problemi ambientali delle coste in tutto il mondo. I rifiuti finiscono in mare, si frammentano in microplastiche e danneggiano la fauna marina e le attività come la pesca. Anche il turismo costiero ne risente, rendendo le pulizie periodiche delle spiagge particolarmente importanti."
   ],
