   "sez": "sport",
   "titolo": "Calcio femminile, il Chelsea travolge il Tottenham con sei gol",
   "orig": "James and Carpenter lead Chelsea surge as sorry Spurs hit for six in WSL again",
   "lead": "Nella Women's Super League inglese il Chelsea ha battuto nettamente il Tottenham segnando sei gol. Protagoniste Lauren James ed Ellie Carpenter, autrici di una doppietta ciascuna. Dopo un primo tempo in cui le ospiti hanno tenuto testa alle avversarie, la squadra di casa ha preso il largo con una serie di reti spettacolari. Con questa vittoria il Chelsea continua a mettere pressione al Manchester City, in testa alla classifica. Lo riferisce The Guardian.",
   "more": [
    "La Women's Super League è il massimo campionato di calcio femminile in Inghilterra. Negli ultimi anni il Chelsea è stato una delle squadre più vincenti del torneo, conquistando numerosi titoli. Il campionato è cresciuto molto per seguito di pubblico e investimenti dei club."
   ],
