   "id": "z883c3c7e",
   "sez": "sport",
   "titolo": "Tennistavolo, Källberg a sorpresa in finale agli Europei",
   "orig": "Anton Källberg klar för EM-final efter skrällseger",
   "lead": "Lo svedese Anton Källberg, 29 anni, si è qualificato per la finale del torneo di singolare degli Europei di tennistavolo. In semifinale ha battuto a sorpresa il tedesco Dang Qiu per 4 set a 2, al termine di una partita piena di capovolgimenti. Il campione Jan-Ove Waldner ha osservato che un anno fa Källberg non sarebbe riuscito a ribaltare la gara. Il giocatore si è detto felicissimo, ma con la finale a poco più di due ore di distanza.",
   "more": [
    "La Svezia ha una grande tradizione nel tennistavolo: Jan-Ove Waldner, campione olimpico nel 1992, è considerato uno dei migliori giocatori di sempre. Negli ultimi decenni il dominio della disciplina è passato soprattutto agli atleti cinesi, ma in Europa svedesi e tedeschi restano tra i più forti."
   ],
