   "id": "z4f1a151f",
   "sez": "economia",
   "titolo": "Nigeria, ESDIAC ottiene la licenza per il mercato dei dati",
   "orig": "ESDIAC secures licence to operate in Nigeria’s data market",
   "lead": "La società ESDIAC ha ottenuto una licenza per operare nel mercato dei dati in Nigeria. L'autorizzazione apre la strada all'espansione dei servizi dell'azienda nel campo delle telecomunicazioni e delle comunicazioni digitali. Con questo via libera, la società potrà ampliare la propria presenza nel Paese africano, in un settore considerato strategico per lo sviluppo economico. Le fonti non indicano tempi né investimenti previsti. Lo riferisce Premium Times.",
   "more": [
    "La Nigeria è il Paese più popoloso dell'Africa e uno dei maggiori mercati delle telecomunicazioni del continente. Le licenze nel settore sono rilasciate dalla Nigerian Communications Commission, l'autorità di regolazione nazionale, che vigila sugli operatori e sulla concorrenza."
   ],
