   "id": "ze1a16d47",
   "sez": "economia",
   "titolo": "Georgia, si dimette un membro del board della Banca nazionale sotto inchiesta",
   "orig": "National Bank of Georgia board member quits amid investigation",
   "lead": "Un componente del consiglio di amministrazione della Banca nazionale della Georgia ha lasciato l'incarico mentre è in corso un'indagine. L'inchiesta è stata avviata dopo che una delle maggiori società georgiane attive nel settore delle criptovalute ha consegnato del materiale probatorio. La fonte non precisa l'identità del dimissionario né il contenuto delle prove presentate o le accuse ipotizzate. Lo riferisce OC Media.",
   "more": [
    "La Banca nazionale della Georgia è l'istituto centrale del Paese caucasico, responsabile della politica monetaria e della vigilanza sul sistema finanziario. La Georgia ha attirato negli anni diverse imprese legate alle criptovalute, anche grazie ai bassi costi dell'energia, settore che rientra nel perimetro di regolamentazione dell'autorità bancaria."
   ],
