   "titolo": "Scontri a Milano, molti minorenni tra i violenti. Genitori increduli in questura",
   "orig": "Scontri Milano, chi sono i violenti: look da maranza e video su TikTok. Genitori increduli: «Iscritti alla privata. Metà sono minori, l'altra metà pirla»",
   "lead": "Chi sono i violenti degli scontri di sabato pomeriggio a Milano? Tra le migliaia di manifestanti scesi in piazza c'erano moltissimi minorenni. Molti di loro avevano un look da \"maranza\" e pubblicavano video su TikTok. In questura sono arrivati i genitori, smarriti: non sapevano cosa stessero facendo i figli quel pomeriggio. Alcuni hanno raccontato che i ragazzi frequentano scuole private. Un genitore ha commentato che metà erano minorenni e l'altra metà «pirla». Lo riferisce Il Messaggero.",
